(async () => {
  try {
    const { value, rowIndex, fieldModel } = arguments[0];
    const rowPrefix = `subform_sub_material.${rowIndex}`;

    if (!value) {
      this.setData({
        [`${rowPrefix}.sub_material_name`]: "",
        [`${rowPrefix}.sub_material_desc`]: "",
        [`${rowPrefix}.sub_material_category`]: null,
        [`${rowPrefix}.sub_material_qty_uom`]: null,
        [`${rowPrefix}.sub_material_qty`]: 0,
        [`${rowPrefix}.sub_material_wastage`]: 0,
        [`${rowPrefix}.sub_material_remark`]: "",
        [`${rowPrefix}.bom_type`]: "standard",
        [`${rowPrefix}.consume_type`]: "USE",
        [`${rowPrefix}.ref_bom_id`]: null,
      });
      this.setOptionData(`${rowPrefix}.ref_bom_id`, []);
      this.disabled([`${rowPrefix}.ref_bom_id`], true);
      return;
    }

    const item = fieldModel?.item || {};

    this.setData({
      [`${rowPrefix}.sub_material_name`]: item.material_name,
      [`${rowPrefix}.sub_material_desc`]: item.material_desc,
      [`${rowPrefix}.sub_material_category`]: item.item_category,
      [`${rowPrefix}.sub_material_qty_uom`]: item.based_uom,
      [`${rowPrefix}.bom_type`]: "standard",
      [`${rowPrefix}.consume_type`]: "USE",
      [`${rowPrefix}.ref_bom_id`]: null,
    });

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    const res = await db
      .collection("bill_of_materials")
      .where({
        parent_material_code: value,
        organization_id: organizationId,
        is_deleted: 0,
        is_active: 1,
      })
      .get();

    // Raw rows would drag their whole subform_sub_material array into the
    // option store; project down to what props + {label,value} need.
    this.setOptionData(
      `${rowPrefix}.ref_bom_id`,
      (res.data || []).map((record) => ({
        id: record.id,
        parent_mat_bom_version: record.parent_mat_bom_version,
        value: record.id,
        label: record.parent_mat_bom_version,
      }))
    );

    // ref_bom_id only applies to a reference line; onChange_bom_type owns it.
    this.disabled([`${rowPrefix}.ref_bom_id`], true);
  } catch (error) {
    console.error("Error loading sub material data:", error);
    this.$message.error(error.message || "Failed to load the sub material");
  }
})();

// BOM_SAVE — the server-side save; see Item Assembly & BOM/BOMsaveWorkflow.json.
const BOM_SAVE_WORKFLOW_ID = "2098308362750185474";

const closeDialog = () => {
  if (this.parentGenerateForm) {
    this.parentGenerateForm.$refs.SuPageDialogRef.hide();
    this.parentGenerateForm.refresh();
    this.hideLoading();
  }
};

const findFieldMessage = (obj) => {
  if (obj && typeof obj === "object") {
    if (obj.field && obj.message) {
      return obj.message;
    }

    if (Array.isArray(obj)) {
      for (const item of obj) {
        const found = findFieldMessage(item);
        if (found) return found;
      }
    }

    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        const found = findFieldMessage(obj[key]);
        if (found) return found;
      }
    }

    return obj.toString();
  }
  return null;
};

(async () => {
  try {
    await this.validate();

    this.showLoading("Saving Bill of Materials...");

    const rawData = this.getValues();
    // default_dialog is the confirmation model, not a column on the table.
    const { default_dialog, ...data } = rawData;
    const pageStatus = data.page_status;

    let workflowResult;

    await this.runWorkflow(
      BOM_SAVE_WORKFLOW_ID,
      { allData: data, pageStatus },
      (res) => {
        workflowResult = res;
      },
      (err) => {
        workflowResult = err;
      },
    );

    if (!workflowResult || !workflowResult.data) {
      this.hideLoading();
      this.$message.error("No response from workflow");
      return;
    }

    const code = workflowResult.data.code;
    if (code && String(code) !== "200") {
      this.hideLoading();
      this.$message.error(
        workflowResult.data.msg ||
          workflowResult.data.message ||
          "Failed to save the Bill of Materials",
      );
      return;
    }

    this.$message.success(
      `${pageStatus === "Edit" ? "Update" : "Add"} successfully.`,
    );
    this.hideLoading();
    closeDialog();
  } catch (error) {
    this.hideLoading();
    console.error(error);

    let errorMessage = "";
    if (error && typeof error === "object") {
      errorMessage = findFieldMessage(error) || "An error occurred";
    } else {
      errorMessage = error;
    }

    this.$message.error(errorMessage);
  }
})();

(async () => {
  try {
    const allData = this.getValues();
    const materialId = allData.parent_material_code;
    const currentId = allData.id;

    this.setData({ default_dialog: {} });

    if (allData.parent_mat_is_default !== 1 || !materialId) return;

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    const res = await db
      .collection("bill_of_materials")
      .where({
        parent_material_code: materialId,
        parent_mat_is_default: 1,
        organization_id: organizationId,
        is_deleted: 0,
      })
      .get();

    // Skip the record being edited, otherwise editing the current default
    // pops a dialog warning about itself.
    const previous = (res.data || []).find(
      (record) => String(record.id) !== String(currentId)
    );
    if (!previous) return;

    this.openDialog("default_dialog");
    this.setData({
      "default_dialog.bom_version": previous.parent_mat_bom_version,
      "default_dialog.bom_id": previous.id,
    });
  } catch (error) {
    console.error("Error checking the default BOM:", error);
    this.$message.error(error.message || "Failed to check the default BOM");
  }
})();

