const { setModelKey, newModel, oldModel } = arguments[0];
const oldData = oldModel+'_type';
const newData = newModel+'_type';
setModelKey(oldData, newData);

const params = this.getComponent("parent_mat_bom_version");
const { options } = params;

if (options?.canManualInput) {
  setTimeout(async () => {
    const maxRetries = 10;
    const interval = 500;
    for (let i = 0; i < maxRetries; i++) {
      const op = await this.onDropdownVisible(
        "parent_mat_bom_version_type",
        true
      );
      if (op != null) break;
      await new Promise((resolve) => setTimeout(resolve, interval));
    }

    const optionsData = this.getOptionData("parent_mat_bom_version_type") || [];
    if (optionsData.some((option) => option.value === -9999)) return;

    this.setOptionData("parent_mat_bom_version_type", [
      { label: "Manual Input", value: -9999 },
      ...optionsData,
    ]);
  }, 200);
}

const { value } = arguments[0];
const pageStatus = this.getValue("page_status");

// On Edit the version is already loaded; only a new record starts blank.
if (pageStatus === "Add" || pageStatus === "Clone") {
  this.setData({ parent_mat_bom_version: "" });
}

this.disabled("parent_mat_bom_version", value !== -9999);

const { value, rowIndex } = arguments[0];
const path = `subform_sub_material.${rowIndex}.ref_bom_id`;

if (value === "reference") {
  this.disabled([path], false);
} else {
  this.setData({ [path]: null });
  this.disabled([path], true);
}

